/// <summary>
/// Table Extension
/// </summary>
[ExtensionOf(tableStr(CustTable))]
Public final class METCustTablePriceEng_Extension
{
}

Method.Source:
    //TODO: Move code to MEtcash model when Metcash Price Engine model is removed
    /// <summary>
    /// CoC Update
    /// </summary>
    public void update(boolean _updateSmmBusRelTable, boolean _updateParty)
    {
        boolean     fieldUpdated = false;
        CustTable   custTableOrig = this.orig();

        if(this.InventSiteId    != custTableOrig.InventSiteId
        || this.taxGroup        != custTableOrig.taxGroup
        || this.invoiceAccount  != custTableOrig.invoiceAccount)
        {
            fieldUpdated = true;
        }
        
        next update(_updateSmmBusRelTable, _updateParty);

        if(fieldUpdated)
        {
            METPriceChangeEventCustomer::metProcessTrackChange(this);
        }
    }
